import {t,label,ui,markup,setText,initLanguage} from './language.mjs';
import {KEY,TYPES,today,yearsBefore,date,emptyData,envelope,readEnvelope,parseText,toText,patientById,ageMonths,vaccineStatus,stockStatus} from './core.mjs';
import {icon} from './icons.mjs';
import {startMotion,animateWorkspace} from './motion.mjs';
import {setupAccounts,patientAccess,saveLinks} from './auth-ui.mjs';
const $=s=>document.querySelector(s);
initLanguage();
for(const link of document.querySelectorAll('#workspace-nav [data-page]'))link.querySelector('span').innerHTML=icon(link.dataset.page);
const FLOWER=markup("<svg class=\"flower-mark\" viewBox=\"0 0 100 100\" fill=\"none\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M50 12v76M12 50h76M23 23l54 54M23 77l54-54\" stroke=\"currentColor\" stroke-width=\"10\" stroke-linecap=\"round\"/></svg>");
const offlineSupported=Boolean(navigator.serviceWorker?.register);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?label('{date}',{date:{date:d,format:'short'}}):'—';
const titles={overview:'Your clinic, at a glance.',mothers:'Mothers’ records',children:'Children’s records',visits:'Visits & notes',vaccines:'Vaccinations',growth:'Child growth',inventory:'Vaccine inventory',guides:'Care guides',backup:'Data & backup',access:'Patient access'};
const singles={mothers:'maternal profile',children:'child profile',visits:'visit',vaccines:'vaccination',growth:'measurement',inventory:'vaccine batch'};
const descriptions={mothers:'Every mother, a story worth keeping close.',children:'Small beginnings. A growing care story.',visits:'Checkups, symptoms, food intake, and the details that matter.',vaccines:'Staff-entered schedules and administered doses. Alerts stay on screen.',growth:'Measurements over time, with your own assessment notes.',inventory:'Batch-level stock, low-stock thresholds, and expiration dates.'};
let store=null;
const staff=()=>store?.account.role==='staff';
const accountUI=setupAccounts(next=>{store=next;route();});
let page='overview',query='',filter='All',editing=null,importStage=null,installEvent=null,toastTimer,offlineReady=false;
let lastFocus=null,formBaseline='';
const data=()=>store?.data??emptyData();
$('.skip-link').addEventListener('click',e=>{e.preventDefault();const target=!$('#auth-view').hidden?$('#auth-main'):$('#workspace-view').hidden?$('#main'):$('#workspace-main');target.tabIndex=-1;target.focus();});
function toast(message){clearTimeout(toastTimer);setText($('#toast'),message);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function info(title,body){setText($('#info-title'),title);$('#info-body').innerHTML=body;$('#info-dialog').showModal();}
$('#close-info').onclick=()=>$('#info-dialog').close();
function updateStorageNotice(){const warning=$('#storage-warning');setText(warning,[store.error,store.sessionWarning].filter(Boolean).map(x=>t(x)).join(' '));warning.hidden=!warning.textContent;setText($('#sync-status'),store.message);$('#account-label').textContent=store.account.displayName+' · '+t(staff()?'Clinic staff':'Patient / guardian');}

const patientLabel=id=>{const p=patientById(data(),id);return p?`${p.name} · ${p.id}`:id;};
const badge=s=>ui`<span class="badge ${['Overdue','Expired'].includes(s)?'danger':['Due today','Low stock','Follow-up needed'].includes(s)?'warning':['Inactive','Not assessed'].includes(s)?'muted':''}">${label(s)}</span>`;
function heading(title,description='',button=''){return ui`<div class="page-heading"><div><p class="eyebrow">KASAMA MO SA PAG-AALAGA.</p><h1>${label(title)}</h1>${description?ui`<p>${label(description)}</p>`:''}</div>${button}</div>`;}
function addButton(type,buttonLabel){if(!staff())return '';return ui`<button class="button primary" data-add="${type}">+ ${label(buttonLabel??`Add ${singles[type]}`)}</button>`;}
function editButton(type,id,buttonLabel='View & edit'){if(!staff())return ui`<button class="row-button" data-view="${type}" data-id="${escape(id)}">View details ↗</button>`;return ui`<button class="row-button" data-edit="${type}" data-id="${escape(id)}" aria-label="${escape(t(buttonLabel)+' '+(data()[type].find(r=>r.id===id)?.name??singles[type]))}" data-ui-attrs="${escape(JSON.stringify({'aria-label':{key:'{action} {name}',params:{action:{ui:buttonLabel},name:data()[type].find(r=>r.id===id)?.name??t(singles[type])}}}))}">${label(buttonLabel)} ↗</button>`;}
function table(headers,rows){return ui`<div class="table-wrap"><table><thead><tr>${headers.map(h=>ui`<th scope="col">${label(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>ui`<tr>${cells.map((c,i)=>ui`<td data-label="${escape(t(headers[i]))}" data-ui-attrs="${escape(JSON.stringify({'data-label':headers[i]}))}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function empty(type,searching=false){if(!staff()&&!searching)return markup('<section class="empty-state"><h2>Your care story belongs here.</h2><p>Your health worker will link your profiles and share care updates with this account. Contact the clinic if a record is missing.</p></section>');return ui`<div class="empty-state"><span class="empty-mark" aria-hidden="true">${type==='children'?FLOWER:'♡'}</span><h2>${label(searching?'No matching records.':type==='mothers'?'A place for every mother.':type==='children'?'A place for every little one.':'A place for every care detail.')}</h2><p>${searching?label('Try another name, ID, or filter.'):label('Your {section} will appear here. Start with a {record}.',{section:{ui:titles[type]},record:{ui:singles[type]}})}</p>${searching?markup('<button class="button secondary" id="clear-search">Clear filters</button>'):addButton(type)}</div>`;}
function renderOverview(){
 if(!staff())return renderPatientOverview();
 const d=data(),now=today();
 const due=d.vaccines.filter(r=>!r.administered).sort((a,b)=>a.scheduled.localeCompare(b.scheduled));
 const overdue=due.filter(r=>r.scheduled<now), low=d.inventory.filter(r=>stockStatus(r)!=='Available');
 const follow=d.growth.filter(r=>r.assessment==='Follow-up needed');
 const recent=[...d.visits].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);
 return heading(titles.overview,'For the people you know, and the community you care for.',addButton('mothers','Add a profile'))+
 ui`<div class="workspace-welcome"><div><h2><span lang="fil">Magandang araw,</span><br><em>ka-barangay.</em></h2><p>${label('{date} · {place}',{date:{date:today(),format:'long'},place:{ui:'Shared clinic workspace'}})}</p></div><span class="welcome-flower" aria-hidden="true">${FLOWER}</span></div><div class="metrics"><div class="metric"><span class="metric-icon">${icon('mothers')}</span><b>${d.mothers.length}</b><span>Maternal profiles</span><small>Registered with the clinic</small></div><div class="metric"><span class="metric-icon">${icon('children')}</span><b>${d.children.length}</b><span>Child profiles</span><small>Every little milestone</small></div><div class="metric"><span class="metric-icon">${icon('vaccines')}</span><b>${overdue.length}</b><span>Overdue vaccinations</span><small>Needs a staff follow-up</small></div><div class="metric"><span class="metric-icon">${icon('inventory')}</span><b>${low.length}</b><span>Stock alerts</span><small>Low or expired batches</small></div></div><div class="workspace-columns"><section class="panel"><h2>The next care moments</h2>${due.slice(0,4).map(r=>ui`<a href="#workspace/vaccines" class="action-row"><div>${escape(patientLabel(r.patient))}<small>${escape(r.vaccine)} · ${escape(r.dose)} · ${fmt(r.scheduled)}</small></div>${badge(vaccineStatus(r))}</a>`).join('')||markup('<p>No pending vaccinations yet. Add staff-confirmed dates in Vaccinations.</p>')}<div class="button-stack"><a class="button secondary" href="#workspace/vaccines">View vaccinations ↗</a></div></section><section class="panel"><h2>A clear view of today</h2><a class="action-row" href="#workspace/visits"><div>Care notes<small>Checkups, symptoms & food records</small></div><span>${d.visits.length}</span></a><a class="action-row" href="#workspace/growth"><div>Growth follow-up<small>Staff-marked records for review</small></div><span>${follow.length}</span></a><a class="action-row" href="#workspace/inventory"><div>Vaccine stock alerts<small>Low stock or expired batches</small></div><span>${low.length}</span></a><a class="action-row" href="#workspace/backup"><div>Keep a copy close<small>Download a complete device backup</small></div><span>↗</span></a></section></div><section class="panel" style="margin-top:26px"><h2>Recent visits</h2>${recent.map(r=>ui`<div class="action-row"><div>${escape(patientLabel(r.patient))}<small>${fmt(r.date)} · ${escape(r.notes.slice(0,100))}</small></div>${editButton('visits',r.id)}</div>`).join('')||markup('<p>Your latest checkups and care notes will appear here.</p>')}<div class="button-stack">${addButton('visits','Record a visit')}</div></section><p class="data-note">Staff changes synchronize to the clinic cloud. Pending offline edits are marked above. Patient accounts receive only the profiles their clinic has linked.</p>`;
}
function rowCells(type,r){
 if(type==='mothers')return [ui`<strong>${escape(r.name)}</strong><small>${escape(r.id)}${r.barangay?' · '+escape(r.barangay):''}</small>`,`${r.age} ${label('years')}`,fmt(r.edd),badge(r.status),editButton(type,r.id)];
 if(type==='children')return [ui`<strong>${escape(r.name)}</strong><small>${escape(r.id)} · ${label(r.gender)}</small>`,`${fmt(r.dob)}<small>${ageMonths(r.dob)} ${label('months')}</small>`,escape(r.motherName),badge(r.status),editButton(type,r.id)];
 if(type==='visits')return [ui`<strong>${escape(patientLabel(r.patient))}</strong><small>${fmt(r.date)}</small>`,`${escape(r.notes.slice(0,110))}${r.notes.length>110?'…':''}`,r.followUp?fmt(r.followUp):'—',editButton(type,r.id)];
 if(type==='vaccines')return [ui`<strong>${escape(patientLabel(r.patient))}</strong><small>${escape(r.vaccine)} · ${escape(r.dose)}</small>`,fmt(r.scheduled),r.administered?fmt(r.administered):'—',badge(vaccineStatus(r)),editButton(type,r.id)];
 if(type==='growth')return [ui`<strong>${escape(patientLabel(r.patient))}</strong><small>${fmt(r.date)}</small>`,`${r.weight} kg`,`${r.height} cm`,badge(r.assessment),editButton(type,r.id)];
 return [ui`<strong>${escape(r.vaccine)}</strong><small>${label('Batch')} ${escape(r.batch)}</small>`,`${r.stock} ${label('doses')}<small>${label('Alert at {count} or fewer',{count:r.threshold})}</small>`,fmt(r.expires),badge(stockStatus(r)),editButton(type,r.id)];
}
const headers={mothers:['Mother','Age','Expected delivery','Status','Actions'],children:['Child','Date of birth','Mother','Status','Actions'],visits:['Patient','Visit notes','Follow-up','Actions'],vaccines:['Patient & vaccine','Scheduled','Administered','Status','Actions'],growth:['Child','Weight','Length / height','Assessment','Actions'],inventory:['Vaccine & batch','Stock','Expiration','Status','Actions']};
function recordStatus(type,r){return type==='vaccines'?vaccineStatus(r):type==='inventory'?stockStatus(r):type==='growth'?r.assessment:r.status??'';}
function filtered(type){return data()[type].filter(r=>(filter==='All'||recordStatus(type,r)===filter)&&Object.values({...r,patient:patientLabel(r.patient??'')}).join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase()));}
function renderRecords(type){
 const opts=type==='mothers'||type==='children'?['Active','Inactive']:type==='vaccines'?['Overdue','Due today','Upcoming','Completed']:type==='inventory'?['Available','Low stock','Expired']:type==='growth'?['Not assessed','Reviewed','Follow-up needed']:[];
 const selected=filtered(type);
 let html=heading(titles[type],descriptions[type],addButton(type));
 if(type==='vaccines')html+=markup('<p class="notice good">Enter vaccination dates confirmed by the health worker. E-Nay calculates due and overdue labels from those dates; it does not generate a clinical immunization schedule or send messages.</p>');
 if(type==='growth')html+=markup('<p class="notice good">Measurements and follow-up flags are recorded by staff. The chart shows recorded weight over time; it does not calculate malnutrition diagnoses or WHO z-scores.</p>');
 html+=ui`<div class="toolbar"><label class="search-box"><span>${label('Search {section}',{section:{ui:titles[type]}})}</span><input id="record-search" type="search" placeholder="Search name, ID, or details…" value="${escape(query)}"></label>${opts.length?ui`<label><span>Filter by status</span><select id="record-filter"><option value="All">${label('All')}</option>${opts.map(s=>ui`<option value="${escape(s)}" ${filter===s?'selected':''}>${label(s)}</option>`).join('')}</select></label>`:''}</div><div id="record-results"><p class="record-count">${label('{shown} of {total} records',{shown:selected.length,total:data()[type].length})}</p>${selected.length?table(headers[type],selected.map(r=>rowCells(type,r))):empty(type,!!query||filter!=='All')}</div>`;
 if(type==='growth'&&data().growth.length)html+=ui`<section class="growth-chart"><h2 class="section-title">A child's growth story</h2><label for="chart-patient">Choose a child</label><select id="chart-patient">${data().children.filter(c=>data().growth.some(g=>g.patient===c.id)).map(c=>ui`<option value="${escape(c.id)}">${escape(c.name)} · ${c.id}</option>`).join('')}</select><div id="chart-content"></div></section>`;
 return html;
}
function refreshResults(){const items=filtered(page);$('#record-results').innerHTML=ui`<p class="record-count">${label('{shown} of {total} records',{shown:items.length,total:data()[page].length})}</p>${items.length?table(headers[page],items.map(r=>rowCells(page,r))):empty(page,!!query||filter!=='All')}`;}
function renderChart(id){const items=data().growth.filter(r=>r.patient===id).sort((a,b)=>a.date.localeCompare(b.date));if(!items.length)return;
 const start=new Date(items[0].date).getTime(),end=new Date(items.at(-1).date).getTime();
 const max=Math.max(...items.map(r=>r.weight))+1,min=Math.max(0,Math.min(...items.map(r=>r.weight))-1);
 const pts=items.map(r=>({x:60+(end===start?230:(new Date(r.date).getTime()-start)/(end-start)*450),y:155-(r.weight-min)/(max-min)*125,r}));
 $('#chart-content').innerHTML=ui`<svg viewBox="0 0 550 190" role="img" aria-label="Recorded weight in kilograms over measurement dates. Exact values are in the table below."><path d="M55 20V160H525" stroke="var(--border)" fill="none"/><text x="5" y="30" fill="var(--text-secondary)" font-size="11">${max.toFixed(1)} kg</text><text x="5" y="160" fill="var(--text-secondary)" font-size="11">${min.toFixed(1)} kg</text><polyline points="${pts.map(p=>`${p.x},${p.y}`).join(' ')}" stroke="var(--primary)" fill="none" stroke-width="2.5"/>${pts.map(p=>ui`<circle cx="${p.x}" cy="${p.y}" r="4" fill="var(--primary)"><title>${fmt(p.r.date)}: ${p.r.weight} kg</title></circle>`).join('')}<text x="55" y="185" fill="var(--text-secondary)" font-size="10">${fmt(items[0].date)}</text>${items.length>1?ui`<text x="525" y="185" fill="var(--text-secondary)" text-anchor="end" font-size="10">${fmt(items.at(-1).date)}</text>`:''}</svg><p>Recorded weight only. A connected line is not a prediction or a reference growth standard.</p>${table(['Date','Weight','Length / height'],items.map(r=>[fmt(r.date),`${r.weight} kg`,`${r.height} cm`]))}`;
}
function renderBackup(){return heading('Keep a copy close.','Clinic records, with an encrypted offline copy for your account.')+ui`<p class="notice good">Cloud records are shared between authorized accounts. Offline edits remain pending until accepted by the server. If another device changes the clinic first, export your pending copy and review it before replacing anything.</p><div class="backup-grid"><section class="panel"><h2>Complete clinic backup</h2><p>Includes all six record types visible to staff. Downloaded backups are plain text: store them privately.</p><div class="button-stack"><button class="button primary" id="download-backup">Download backup ↧</button><button class="button secondary" id="persist-storage">Keep device storage</button></div></section><section class="panel"><h2>Restore or import</h2><p>Review a backup or Java text file before replacing clinic records. Old device records are never uploaded automatically.</p><label for="import-kind">File type</label><select id="import-kind"><option value="backup">Complete web backup (.json)</option><option value="mothers">Java maternal profiles (.txt)</option><option value="children">Java child profiles (.txt)</option></select><label for="import-file">Choose a file to review</label><input id="import-file" type="file" accept=".json,application/json"><button class="button secondary" id="review-legacy">Review records from the previous app</button><div id="import-preview" class="import-preview" aria-live="polite"></div></section><section class="panel"><h2>Java compatibility</h2><p>Only original profile fields fit Java text files. Contacts, barangay, visits and other care data require the complete backup.</p><div class="button-stack"><button class="button secondary" data-export="mothers">Maternal .txt ↧</button><button class="button secondary" data-export="children">Child .txt ↧</button></div></section><section class="panel"><h2>Refresh from the clinic</h2><p>Refreshing requires an online sign-in. Pending changes are preserved unless you explicitly choose to replace them. Download a backup first.</p><div class="button-stack"><button class="button secondary" id="reload-storage">Load latest clinic copy</button><button class="button secondary" id="discard-pending">Replace pending copy from cloud</button><button class="button secondary install-action">Install on this device ↗</button></div></section></div>`;}
function renderPatientOverview(){const d=data(),profiles=[...d.mothers,...d.children],pending=d.vaccines.filter(v=>!v.administered);return heading('Your care, close by.','Care updates shared by your barangay health worker.')+ui`<div class="workspace-welcome"><div><h2><span lang="fil">Magandang araw,</span> <em>${escape(store.account.displayName)}.</em></h2><p>Your account shows only clinic-linked care profiles.</p></div><span class="welcome-flower" aria-hidden="true">${FLOWER}</span></div>${profiles.length?'<section class="panel"><h2>Your family profiles</h2>'+profiles.map(p=>'<a class="action-row" href="#workspace/'+(p.id.startsWith('M')?'mothers':'children')+'"><div>'+escape(p.name)+'<small>'+escape(p.id)+'</small></div><span>View ↗</span></a>').join('')+'</section>':'<section class="panel"><h2>Let’s connect your care.</h2><p>Give your username <strong>'+escape(store.account.username)+'</strong> to your health worker. After verifying your identity, the clinic can link your own or your child’s profile.</p></section>'}<section class="panel" style="margin-top:24px"><h2>Your next vaccinations</h2>${pending.map(v=>'<a class="action-row" href="#workspace/vaccines"><div>'+escape(patientLabel(v.patient))+'<small>'+escape(v.vaccine)+' · '+fmt(v.scheduled)+'</small></div>'+badge(vaccineStatus(v))+'</a>').join('')||'<p>No pending doses have been shared yet.</p>'}</section><p class="data-note">Clinical records and inventory are managed by clinic staff. Contact your health worker about corrections or missing information. The app does not replace clinical advice.</p>`;}

const guides=[
 {k:'MATERNAL CARE',title:'Make space for the conversation.',body:'Antenatal care includes nutrition counselling and ongoing contact with a health professional. Use each visit to record the mother’s questions, symptoms, and the follow-up agreed with her provider.',items:['Keep the expected delivery date and contact information current.','Record concerns in the visit notes for the attending health professional.','Use the local clinic’s approved care and referral protocols.'],source:'WHO · Nutrition counselling during pregnancy',url:'https://www.who.int/tools/elena/interventions/nutrition-counselling-pregnancy'},
 {k:'INFANT FEEDING',title:'Support the first two years.',body:'WHO recommends exclusive breastfeeding for the first six months, then safe, nutritionally adequate complementary foods with continued breastfeeding up to two years or beyond.',items:['Record feeding questions and dietary notes during the visit.','Ask the qualified health professional for individual feeding support.','Keep the child’s date of birth accurate so age is calculated correctly.'],source:'WHO · Infant and young child feeding',url:'https://www.who.int/news-room/fact-sheets/detail/infant-and-young-child-feeding'},
 {k:'GROWTH RECORDS',title:'Measure. Record. Review.',body:'Growth assessment uses weight and length or height, interpreted against appropriate growth standards. This version records measurements and staff-entered follow-up flags; it does not perform that clinical interpretation.',items:['Enter weight in kilograms and length or height in centimetres.','Check the measurement date and patient before saving.','Record the health worker’s assessment and next steps in the notes.'],source:'WHO · Growth assessment and counselling',url:'https://www.who.int/publications/m/item/10-steps-to-successful-growth-assessment-and-counselling'},
 {k:'BEFORE A HOME VISIT',title:'Bring the workspace with you.',body:'A little preparation makes offline visits easier. The workspace, these short guides, and your local records remain available after the first successful offline download.',items:['Wait for “Offline ready” while you still have a connection.','Open the profiles you need and check that your device is charged.','Download a complete backup regularly. External reading links need internet.'],source:'E-Nay · Local workspace guide',url:''}
];
function renderGuides(){return heading('A little guidance, close by.','These short guides are saved with the app. External reading needs a connection.')+ui`<p class="notice good">General information for health workers. Follow approved local protocols and qualified clinical guidance. Sources reviewed 18 October 2026.</p><div class="guide-grid">${guides.map((g,i)=>ui`<article><p class="eyebrow">0${i+1} / ${label(g.k)}</p><h2>${label(g.title)}</h2><p>${label(g.body)}</p><ul>${g.items.map(x=>ui`<li>${label(x)}</li>`).join('')}</ul>${g.url?ui`<a class="external-resource" href="${g.url}" target="_blank" rel="noopener noreferrer">${label(g.source)} ↗</a>`:ui`<p class="data-note">${label(g.source)}</p>`}</article>`).join('')}</div>`;}
function render(){
 updateStorageNotice();$('#page-content').innerHTML=page==='access'?heading('Patient access','Link verified patient accounts to their own care profiles.')+markup('<p id="access-loading">Loading patient accounts…</p>'):page==='overview'?renderOverview():page==='backup'?renderBackup():page==='guides'?renderGuides():renderRecords(page);
 $('#workspace-nav').querySelectorAll('a').forEach(a=>{if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(page==='access'){const activeStore=store;patientAccess(store).then(html=>{if(page==='access'&&store===activeStore)$('#page-content').innerHTML=heading('Patient access','Link verified patient accounts to their own care profiles.')+html;}).catch(error=>{if(page==='access'&&store===activeStore)setText($('#access-loading'),error.message);});}
 if($('#chart-patient'))renderChart($('#chart-patient').value);
}
function route(){const wasWorkspace=!$('#workspace-view').hidden,previousPage=page;const hash=location.hash.slice(1);const workspace=hash==='workspace'||hash.startsWith('workspace/');$('#home-view').hidden=workspace;$('#workspace-view').hidden=!workspace||!store;
 accountUI.hide();if(workspace&&!store){accountUI.show();$('.skip-link').href='#auth-main';document.title=t('Sign in')+' — E-Nay';return;}
 $('.skip-link').href=workspace?'#workspace-main':'#main';
 if(workspace){const next=hash.split('/')[1]||'overview';page=Object.hasOwn(titles,next)&& (staff()||!['inventory','backup','access'].includes(next))?next:'overview';$('#mobile-page').value=page;for(const el of document.querySelectorAll('[data-page],#mobile-page option')){const key=el.dataset.page??el.value;el.hidden=!staff()&&['inventory','backup','access'].includes(key);el.disabled=el.hidden;}query='';filter='All';importStage=null;render();if(!wasWorkspace||previousPage!==page)animateWorkspace();}
 document.title=workspace?`${t(titles[page])} — E-Nay`:'E-Nay — '+t('Care, closer to home');
}
window.addEventListener('hashchange',()=>{route();if(location.hash.startsWith('#workspace')||location.hash==='#home'||!location.hash)window.scrollTo(0,0);});route();
const field=(key,label,kind='text',extra={})=>({key,label,kind,...extra});
function fields(type){
 const profile=[field('id','Profile ID','text',{hint:type==='mothers'?'M + exactly 3 digits, e.g. M001':'C + exactly 3 digits, e.g. C001',placeholder:type==='mothers'?'M001':'C001'}),field('name',type==='mothers'?'Mother’s name':'Child’s name','text',{autocomplete:'name'}),field('status','Monitoring status','select',{options:['Active','Inactive']}),field('contact','Contact number','tel',{optional:true,placeholder:'09… or +63…'}),field('barangay','Barangay / location','text',{optional:true,wide:true})];
 if(type==='mothers')return [profile[0],profile[1],field('age','Age in years','number',{min:12,max:60,step:1}),field('edd','Expected delivery date','date'),...profile.slice(2)];
 if(type==='children')return [profile[0],profile[1],field('gender','Sex recorded at birth','select',{options:['Female','Male']}),field('dob','Date of birth','date'),field('motherName','Mother’s name'),...profile.slice(2)];
 const patients=(type==='growth'?data().children:[...data().mothers,...data().children]).map(p=>({value:p.id,label:`${p.name} · ${p.id}`}));
 const patient=field('patient',type==='growth'?'Child profile':'Patient profile','select',{options:patients,wide:true});
 if(type==='visits')return [patient,field('date','Visit date','date'),field('followUp','Next follow-up','date',{optional:true}),field('bloodPressure','Blood pressure as recorded','text',{optional:true,placeholder:'e.g. 120/80 mmHg',hint:'Transcribe the clinician’s reading.'}),field('notes','Checkup notes','textarea',{wide:true}),field('symptoms','Reported symptoms','textarea',{wide:true,optional:true}),field('food','Food intake / dietary notes','textarea',{wide:true,optional:true})];
 if(type==='vaccines')return [patient,field('vaccine','Vaccine name'),field('dose','Dose / schedule label','text',{placeholder:'e.g. Dose 1'}),field('scheduled','Scheduled date','date'),field('administered','Date administered','date',{optional:true,hint:'Leave blank while the dose is pending.'}),field('notes','Notes','textarea',{optional:true,wide:true})];
 if(type==='growth')return [patient,field('date','Measurement date','date'),field('assessment','Health worker assessment','select',{options:['Not assessed','Reviewed','Follow-up needed']}),field('weight','Weight (kg)','number',{step:'any',min:.1,max:100}),field('height','Length / height (cm)','number',{step:'any',min:10,max:200}),field('notes','Assessment / follow-up notes','textarea',{optional:true,wide:true})];
 return [field('vaccine','Vaccine name'),field('batch','Batch ID'),field('stock','Available doses','number',{min:0,max:100000,step:1}),field('threshold','Low-stock alert at','number',{min:0,max:100000,step:1,hint:'Alert when available doses are at or below this number.'}),field('expires','Expiration date','date')];
}
function openForm(type,id=null){
 if(!staff()){toast('Only clinic staff can change clinical records.');return;}
 if(store.blocked){toast('Storage needs attention. Open Data & backup before making changes.');return;}
 if(!TYPES.includes(type))return;
 if(!['mothers','children','inventory'].includes(type)&&!(type==='growth'?data().children.length:data().mothers.length+data().children.length)){toast(type==='growth'?'Add a child profile before recording growth.':'Add a patient profile before recording care.');return;}
 lastFocus=document.activeElement;const original=id?data()[type].find(r=>r.id===id):null;if(id&&!original){toast('That record no longer exists. Reload the workspace.');return;}
 editing={type,id};setText($('#form-title'),`${id?'Edit':'Add'} ${singles[type]}`);$('#form-error').hidden=true;
 const defaults={status:'Active',gender:'Female',assessment:'Not assessed',date:today(),threshold:5,stock:0};
 if(!id&&(type==='mothers'||type==='children')){const prefix=type==='mothers'?'M':'C';for(let n=1;n<=999;n++){const candidate=prefix+String(n).padStart(3,'0');if(!data()[type].some(r=>r.id===candidate)){defaults.id=candidate;break;}}}
 $('#form-fields').innerHTML=fields(type).map(f=>{const value=original?.[f.key]??defaults[f.key]??'';const opts=(f.options??[]).map(x=>typeof x==='string'?{value:x,label:x}:x);let control;
 const attrs=`id="field-${f.key}" name="${f.key}" ${!f.optional?'required':''} aria-describedby="error-${f.key}${f.hint?' hint-'+f.key:''}"`;
 if(f.kind==='select')control=ui`<select ${attrs}>${f.key==='patient'?'<option value="">Choose a profile…</option>':''}${opts.map(o=>ui`<option value="${escape(o.value)}" ${o.value===value?'selected':''}>${f.key==='patient'?escape(o.label):label(o.label)}</option>`).join('')}</select>`;
 else if(f.kind==='textarea')control=ui`<textarea ${attrs} maxlength="2000">${escape(value)}</textarea>`;
 else control=ui`<input ${attrs} type="${f.kind}" value="${escape(value)}" ${f.placeholder?`placeholder="${escape(t(f.placeholder))}" data-ui-attrs="${escape(JSON.stringify({placeholder:f.placeholder}))}"`:''} ${f.autocomplete?`autocomplete="${f.autocomplete}"`:''} ${f.kind==='text'?'maxlength="100"':''} ${f.kind==='tel'?'maxlength="40"':''} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.step!==undefined?`step="${f.step}"`:''} ${f.key==='id'&&id?'disabled':''} ${f.kind==='number'?'inputmode="decimal"':''}>`;
 return ui`<div class="field ${f.wide?'wide':''} ${f.key==='name'||f.key==='motherName'?'wide-mobile':''}"><label for="field-${f.key}">${label(f.label)}${f.optional?' <span>(optional)</span>':''}</label>${control}${f.hint?ui`<span class="hint" id="hint-${f.key}">${label(f.hint)}</span>`:''}<span id="error-${f.key}" class="field-error" aria-live="polite"></span></div>`;}).join('');
 if(!id){if(type==='mothers')$('#field-edd').min=today();if(type==='children'){$('#field-dob').min=yearsBefore(today(),2);$('#field-dob').max=today();}}
 if($('#field-administered'))$('#field-administered').max=today();
 if($('#field-date'))$('#field-date').max=today();
 formBaseline=JSON.stringify(Object.fromEntries(new FormData($('#record-form'))));$('#form-dialog').showModal();
}
function closeForm(){const changed=JSON.stringify(Object.fromEntries(new FormData($('#record-form'))))!==formBaseline;if(changed&&!window.confirm(t('Discard the unsaved values in this form?')))return;$('#form-dialog').close();lastFocus?.focus();}
$('#close-form').onclick=closeForm;$('#cancel-form').onclick=closeForm;$('#form-dialog').addEventListener('cancel',e=>{e.preventDefault();closeForm();});
$('#record-form').onsubmit=async e=>{e.preventDefault();if(!editing)return;const form=e.currentTarget;const raw=Object.fromEntries(new FormData(form));if(editing.id)raw.id=editing.id;
 form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));form.querySelectorAll('.field-error').forEach(x=>setText(x,''));$('#form-error').hidden=true;
 const submit=form.querySelector('[type=submit]');submit.disabled=true;
 try{const save=()=>store.save(editing.type,raw,editing.id);if(navigator.locks)await navigator.locks.request('enay-record-write',save);else await save();$('#form-dialog').close();render();toast(store.pending?'Saved in your encrypted offline copy. Clinic sync is pending.':'Record saved to the clinic.');lastFocus?.focus();}
 catch(error){setText($('#form-error'),error.message);$('#form-error').hidden=false;if(error.field){const el=$(`#field-${error.field}`);if(el){el.setAttribute('aria-invalid','true');setText($(`#error-${error.field}`),error.message);el.focus();}}}
 finally{submit.disabled=false;}
};
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function stageImport(content,kind){
 let next,errors=[];const countBefore=TYPES.reduce((n,k)=>n+data()[k].length,0);
 if(kind==='backup')next=readEnvelope(content).data;
 else{
  if(store.blocked)throw new Error('Use a complete web backup to recover unreadable storage.');
  const parsed=parseText(content,kind);errors=parsed.errors;next=structuredClone(data());next[kind]=parsed.records;
  // Keep existing browser-only fields on a matching imported profile.
  next[kind]=next[kind].map(r=>({...r,contact:data()[kind].find(x=>x.id===r.id)?.contact??'',barangay:data()[kind].find(x=>x.id===r.id)?.barangay??''}));
  const ids=new Set([...next.mothers,...next.children].map(r=>r.id));
  if(['visits','vaccines','growth'].some(t=>next[t].some(r=>!ids.has(r.patient))))throw new Error('This import would remove profiles referenced by care records. Restore a complete backup or retain those profiles in the text file. Nothing was changed.');
 }
 importStage={next,raw:store.raw,errors};
 const count=TYPES.reduce((n,k)=>n+next[k].length,0);
 return ui`<div class="notice ${errors.length?'warning':'good'}"><strong>Ready to review</strong><br>${kind==='backup'?label('Complete workspace: {before} existing records → {count} imported records.',{before:countBefore,count}):label('{count} valid {kind} profiles. {errors} invalid rows will be skipped.',{count:next[kind].length,kind:{ui:kind==='mothers'?'maternal profile':'child profile'},errors:errors.length})}<br>Patient account links will be cleared for staff verification after this replacement. Nothing has been changed yet.</div>${errors.length?ui`<ul>${errors.map(s=>ui`<li>${label(s)}</li>`).join('')}</ul>`:''}<label class="confirm-check"><input id="confirm-import" type="checkbox"><span>${label('I have reviewed this file and understand it will replace {target}{skipped}.',{target:{ui:kind==='backup'?'all records in this workspace':kind==='mothers'?'the maternal profile list':'the child profile list'},skipped:{ui:errors.length?' and skip the invalid rows':''}})}</span></label><button class="button primary" id="apply-import" disabled>Confirm & replace records</button>`;
}
document.addEventListener('click',async e=>{
 const add=e.target.closest('[data-add]'),edit=e.target.closest('[data-edit]'),exp=e.target.closest('[data-export]');
 if(add)openForm(add.dataset.add);
 if(edit)openForm(edit.dataset.edit,edit.dataset.id);
 if(exp&&staff())download(exp.dataset.export==='mothers'?'maternal_records.txt':'child_records.txt',toText(data()[exp.dataset.export],exp.dataset.export),'text/plain;charset=utf-8');
 if(e.target.closest('#clear-search')){query='';filter='All';render();}
 if(e.target.closest('#download-backup')&&staff())download(`E-Nay-backup-${today()}.json`,JSON.stringify(envelope(data()),null,2));
 if(e.target.closest('#download-original')){if(store.raw!==null)download(`E-Nay-original-storage-${today()}.txt`,store.raw,'text/plain');else toast('No stored data could be read. Check your browser’s storage permissions.');}
 if(e.target.closest('#reload-storage')||e.target.closest('#discard-pending')){try{const discard=!!e.target.closest('#discard-pending');if(discard&&!window.confirm(t('Replace this device’s pending edits with the latest clinic copy? Download a backup first.')))return;await store.load({discard});importStage=null;render();toast('Latest authorized clinic copy loaded.');}catch(error){toast(error.message);}}
 if(e.target.closest('#sync-records')){await store.sync();if(!store.pending&&store.proof){try{await store.load();}catch(error){store.error=error.message;}}if(store)render();}
 if(e.target.closest('#sign-out')){const previous=store;store=null;$('#page-content').replaceChildren();if($('#form-dialog').open)$('#form-dialog').close();editing=null;importStage=null;formBaseline='';lastFocus=null;$('#form-fields').replaceChildren();$('#info-body').replaceChildren();if($('#info-dialog').open)$('#info-dialog').close();accountUI.reset();route();await previous?.signOut();}
 if(e.target.closest('[data-view]')){const el=e.target.closest('[data-view]'),record=data()[el.dataset.view].find(r=>r.id===el.dataset.id),fieldNames={"id":"Record ID","name":"Your name","age":"Age","edd":"Expected delivery date","status":"Status","contact":"Contact number","barangay":"Barangay / location","gender":"Sex recorded at birth","dob":"Date of birth","motherName":"Mother’s name","patient":"Patient","date":"Date","followUp":"Next follow-up","bloodPressure":"Blood pressure as recorded","notes":"Notes","symptoms":"Reported symptoms","food":"Food intake / dietary notes","vaccine":"Vaccine name","dose":"Dose / schedule label","scheduled":"Scheduled date","administered":"Date administered","weight":"Weight (kg)","height":"Length / height (cm)","assessment":"Health worker assessment"};if(record)info('Your care record',Object.entries(record).map(([key,value])=>ui`<p><strong>${label(fieldNames[key]??key)}</strong><br>${['status','gender','assessment'].includes(key)?label(value):escape(value||'—')}</p>`).join(''));}
 if(e.target.closest('#review-legacy')&&staff()){try{const raw=localStorage.getItem(KEY);if(!raw)throw new Error('No records from the previous app were found in this browser.');$('#import-kind').value='backup';$('#import-preview').innerHTML=stageImport(raw,'backup');}catch(error){toast(error.message);}}
 if(e.target.closest('#persist-storage')){try{const allowed=await navigator.storage?.persist?.();toast(allowed?'Persistent storage granted. Continue to keep backups.':'Your browser did not grant persistent storage. Keep regular downloaded backups.');}catch{toast('Persistent storage is unavailable in this browser. Keep regular backups.');}}
 if(staff()&&e.target.closest('#apply-import')&&importStage&&$('#confirm-import')?.checked){
  try{if(importStage.raw!==store.raw)throw new Error('Records changed after this preview. Choose the file again.');const restore=()=>store.commit(importStage.next,{recover:true});if(navigator.locks)await navigator.locks.request('enay-record-write',restore);else await restore();importStage=null;render();toast(store.pending?'Reviewed records saved offline; clinic sync is pending.':'Reviewed records saved to the clinic.');}
  catch(error){$('#import-preview').insertAdjacentHTML('beforeend',ui`<p class="notice warning" role="alert">${label(error.message)}</p>`);}
 }
 if(e.target.closest('.install-action'))installApp();
 if(e.target.closest('.external-resource')&&!navigator.onLine){e.preventDefault();toast('No internet connection. The external link is unavailable; the guide above still works offline.');}
 if(e.target.closest('#photo-credits'))info('Real people. Real photography.',ui`<p>The website uses licensed photography by human photographers. No AI-generated images are used.</p><p><a href="https://www.pexels.com/photo/asia-fujifilm-street-photo-street-photography-27848687/" target="_blank" rel="noopener">Mother and baby in Manila — Zachary Angeles / Pexels</a></p><p><a href="https://www.pexels.com/photo/mother-and-child-overlooking-cagayan-valley-view-29698711/" target="_blank" rel="noopener">Mother and child in Cagayan Valley — Sharmaine Monticalbo / Pexels</a><br><a href="https://www.pexels.com/license/" target="_blank" rel="noopener">Pexels license</a></p><p>Photographs are illustrative. The people shown are not identified as E-Nay patients or endorsers.</p>`);
});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){query=e.target.value;refreshResults();}});
document.addEventListener('change',async e=>{
 if(e.target.id==='mobile-page')location.hash=e.target.value==='overview'?'workspace':`workspace/${e.target.value}`;
 if(e.target.id==='record-filter'){filter=e.target.value;refreshResults();}
 if(e.target.id==='chart-patient')renderChart(e.target.value);
 if(e.target.id==='confirm-import')$('#apply-import').disabled=!e.target.checked;
 if(e.target.id==='import-kind'){importStage=null;$('#import-file').value='';$('#import-file').accept=e.target.value==='backup'?'.json,application/json':'.txt,text/plain';$('#import-preview').innerHTML='';}
 if(e.target.id==='import-file'){
  importStage=null;const file=e.target.files?.[0],kind=$('#import-kind').value;if(!file)return;
  const preview=$('#import-preview');setText(preview,'Reading file…');
  try{if(file.size>10*1024*1024)throw new Error('Choose a file smaller than 10 MB. Nothing has been changed.');const content=await file.text();if(!document.contains(preview)||$('#import-kind').value!==kind||$('#import-file').files?.[0]!==file)return;delete preview.dataset.uiText;preview.innerHTML=stageImport(content,kind);}
  catch(error){preview.innerHTML=ui`<p class="notice warning" role="alert">${label(error.message)} ${label('Existing records were preserved.')}</p>`;}
 }
});
document.addEventListener('submit',e=>{if(e.target.matches('.patient-link-form')){e.preventDefault();if(staff())saveLinks(e.target,store);}});
window.addEventListener('beforeunload',e=>{if($('#form-dialog').open&&JSON.stringify(Object.fromEntries(new FormData($('#record-form'))))!==formBaseline){e.preventDefault();e.returnValue='';}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('appinstalled',()=>{installEvent=null;toast('E-Nay is installed. Wait for Offline ready before disconnecting.');});
async function installApp(){if(installEvent){await installEvent.prompt();installEvent=null;return;}info('Take E-Nay with you.',ui`<p>If this link opened inside Messenger or another app, use its menu to open it in your browser, or copy the link into Safari or Chrome.</p><p><strong>Android:</strong> Open this site in Chrome or Edge, open the browser menu, then choose “Install app” or “Add to Home screen.”</p><p><strong>iPhone or iPad:</strong> Open this site in Safari, tap Share, then “Add to Home Screen.” Turn on “Open as Web App” if shown, then tap Add.</p><p><strong>Computer:</strong> Use your browser’s install icon or app menu when available.</p><p>Open the installed app while connected and wait for <strong>Offline ready</strong>. Sign in online to download your authorized records. Your encrypted offline copy needs your account password to unlock. Staff changes made offline are pending until accepted by the clinic. Installation availability depends on your browser.</p>`);}
function connection(){const status=$('#offline-status');if(!offlineSupported){setText(status,'Offline unavailable here');return;}setText(status,offlineReady?(navigator.onLine?'Offline ready · App downloaded':'Offline · App downloaded'):(navigator.onLine?'Preparing offline access…':'Offline copy not confirmed'));}
window.addEventListener('online',()=>{connection();if(store)store.sync().then(()=>{if(store&&!$('#workspace-view').hidden)updateStorageNotice();});});window.addEventListener('offline',connection);connection();
if(offlineSupported){
 navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_READY'){offlineReady=true;connection();}});
 const checkCachedShell=()=>navigator.serviceWorker.controller?.postMessage({type:'CHECK_OFFLINE'});
 // A browser may reject register() while offline even when an installed worker
 // controls this page. Check that worker independently of network registration.
 checkCachedShell();
 navigator.serviceWorker.ready.then(reg=>{(navigator.serviceWorker.controller??reg.active)?.postMessage({type:'CHECK_OFFLINE'});});
 navigator.serviceWorker.register('./sw.js').then(checkCachedShell).catch(()=>{if(navigator.serviceWorker.controller)checkCachedShell();else if(!offlineReady)setText($('#offline-status'),'Offline setup unavailable');});
 navigator.serviceWorker.addEventListener('controllerchange',checkCachedShell);
}else {connection();$('#offline-guidance').hidden=false;}

document.addEventListener('enay-language-change',()=>{if(store)updateStorageNotice();document.title=location.hash.startsWith('#workspace')?(store?t(titles[page]):t('Sign in'))+' — E-Nay':'E-Nay — '+t('Care, closer to home');});
startMotion();
